<?php
namespace App\Http\Controllers; use App\Models\{Attendance,SchoolClass,Student,Teacher};
class DashboardController extends Controller{public function __invoke(){$u=auth()->user();$classId=$u->isWali()?$u->class_id:request('class_id');$sq=Student::query()->when($classId,fn($q)=>$q->where('class_id',$classId));$aq=Attendance::whereDate('attendance_date',today())->when($classId,fn($q)=>$q->whereHas('student',fn($s)=>$s->where('class_id',$classId)));$stats=['students'=>(clone $sq)->count(),'teachers'=>Teacher::count(),'classes'=>SchoolClass::count()];foreach(['hadir','terlambat','izin','sakit','alfa'] as $s)$stats[$s]=(clone $aq)->where('status',$s)->count();$recent=(clone $aq)->with('student.schoolClass')->latest()->limit(8)->get();return view('dashboard',compact('stats','recent'));}}
